package xyz.kuailemao.diary.ai;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static xyz.kuailemao.diary.ai.DiaryAiModels.*;

@EnabledIfEnvironmentVariable(named="BLOG_DIARY_AI_QA",matches="true")
class DiaryDiagnosticsPostgresTest {
    DiaryAiPostgresTest fixture;DiaryDiagnostics diagnostics;
    @BeforeAll static void connect(){DiaryAiPostgresTest.connect();CoachingPeriodAiTest.connect();}
    @AfterAll static void close(){DiaryAiPostgresTest.close();CoachingPeriodAiTest.close();}
    @BeforeEach void setup() throws Exception {fixture=new DiaryAiPostgresTest();fixture.fixture();diagnostics=new DiaryDiagnostics(DiaryAiPostgresTest.jdbc,DiaryAiPostgresTest.tx);}
    @AfterEach void stop(){fixture.stop();}
    record Failed(UUID job,UUID entry) {}
    Failed failReview(){
        UUID entry=fixture.entry("今天散步十五分钟。");var scope=fixture.selected(entry);var preview=fixture.store.preview(fixture.owner,scope);
        var job=fixture.store.enqueue(fixture.owner,Kind.REVIEW,new Request(UUID.randomUUID(),null,scope,preview.snapshotDigest(),false));fixture.reply.set("PRIVATE_PROBE");
        var p=spy(fixture.p);doReturn(true).when(p).configured();var worker=new DiaryAiWorker(fixture.store,fixture.index,fixture.cloud,p,fixture.owner,()->true);
        try{worker.tick();assertEquals(State.FAILED,fixture.store.job(fixture.owner,job.id()).state());assertNull(fixture.store.job(fixture.owner,job.id()).reportId());assertTrue(fixture.store.job(fixture.owner,job.id()).possiblyCharged());int before=fixture.calls.get();worker.tick();assertEquals(before,fixture.calls.get());}finally{worker.close();}return new Failed(job.id(),entry);
    }
    @Test void failureIsPrivateInspectableAndIdempotentlyDeletable(){var task=failReview();var metadata=diagnostics.read(fixture.owner,task.job(),"REVIEW",false);assertEquals("JSON_PARSE",metadata.reason());assertNull(metadata.raw());assertTrue(metadata.sources().isEmpty());var body=diagnostics.read(fixture.owner,task.job(),"REVIEW",true);assertEquals("PRIVATE_PROBE",body.raw());assertEquals(1,body.sources().size());assertEquals("NOT_RECORDED",diagnostics.read(fixture.owner+1,task.job(),"REVIEW",true).status());diagnostics.delete(fixture.owner,task.job(),"REVIEW");diagnostics.delete(fixture.owner,task.job(),"REVIEW");assertNull(diagnostics.read(fixture.owner,task.job(),"REVIEW",true).raw());assertEquals("DELETED",diagnostics.read(fixture.owner,task.job(),"REVIEW",false).status());}
    @Test void expiredOutputCannotBeReadAndCleanupWorksWithoutGeneration(){var task=failReview();fixture.store.tx(fixture.owner,()->{DiaryAiPostgresTest.jdbc.update("UPDATE diary_diagnostics.failure SET created_at=now()-interval '8 days',expires_at=now()-interval '1 day' WHERE owner_id=:owner",Map.of("owner",fixture.owner));return null;});int before=fixture.calls.get();diagnostics.cleanup(fixture.owner);var result=diagnostics.read(fixture.owner,task.job(),"REVIEW",true);assertEquals("EXPIRED",result.status());assertNull(result.raw());assertTrue(result.sources().isEmpty());assertEquals(before,fixture.calls.get());}
    @Test void sourceRevisionChangeRemovesDiagnosticCopy(){var task=failReview();fixture.store.tx(fixture.owner,()->{DiaryAiPostgresTest.jdbc.update("UPDATE diary.entry SET revision=revision+1 WHERE owner_id=:owner AND id=:id",Map.of("owner",fixture.owner,"id",task.entry()));return null;});var value=diagnostics.read(fixture.owner,task.job(),"REVIEW",true);assertEquals("STALE",value.status());assertNull(value.raw());assertTrue(value.sources().isEmpty());}
    @Test void deletedSourceAndPrivateLogProbe(){var logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(DiaryAiStore.class);var capture=new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();capture.start();logger.addAppender(capture);try{var task=failReview();assertTrue(capture.list.stream().anyMatch(e->e.getFormattedMessage().contains("reason=JSON_PARSE")));assertTrue(capture.list.stream().noneMatch(e->e.getFormattedMessage().contains("PRIVATE_PROBE")));fixture.store.tx(fixture.owner,()->{DiaryAiPostgresTest.jdbc.update("UPDATE diary.entry SET deleted_at=now() WHERE owner_id=:owner AND id=:id",Map.of("owner",fixture.owner,"id",task.entry()));return null;});assertEquals("STALE",diagnostics.read(fixture.owner,task.job(),"REVIEW",true).status());}finally{logger.detachAppender(capture);capture.stop();}}
    @Test void boundsAndHistoricalMissingAreExplicit(){assertEquals("NOT_RECORDED",diagnostics.read(fixture.owner,UUID.randomUUID(),"REVIEW",true).status());var issue=assertThrows(DiaryValidation.Issue.class,()->DiaryValidation.check("INVALID",List.of(),"REVIEW"));UUID id=UUID.randomUUID();fixture.store.tx(fixture.owner,()->{diagnostics.save(fixture.owner,id,"REVIEW",issue,"fixture","fixture","x".repeat(131073),List.of());return null;});var value=diagnostics.read(fixture.owner,id,"REVIEW",true);assertEquals("NOT_RETAINED",value.status());assertEquals("JSON_PARSE",value.reason());assertNull(value.raw());}
    @Test void questionAlsoRetainsItsFailureWithoutChangingTheDiary(){UUID entry=fixture.entry("今天散步十五分钟。");fixture.indexAll();fixture.reply.set("INVALID_QUESTION");var job=fixture.store.enqueue(fixture.owner,Kind.QUESTION,fixture.question(fixture.selected(entry)));var p=spy(fixture.p);doReturn(true).when(p).configured();var worker=new DiaryAiWorker(fixture.store,fixture.index,fixture.cloud,p,fixture.owner,()->true);try{worker.tick();assertEquals(State.FAILED,fixture.store.job(fixture.owner,job.id()).state());assertEquals("INVALID_QUESTION",diagnostics.read(fixture.owner,job.id(),"QUESTION",true).raw());assertEquals(1,fixture.diary.read(fixture.owner,entry).revision());}finally{worker.close();}}
    @Test void periodAlsoRetainsItsFailure() throws Exception {var period=new CoachingPeriodAiTest();period.fixture();try{period.server.removeContext("/model");period.server.createContext("/model",e->{period.calls.incrementAndGet();e.getRequestBody().readAllBytes();byte[] bytes="{\"choices\":[{\"finish_reason\":\"stop\",\"message\":{\"content\":\"INVALID_PERIOD\"}}]}".getBytes(java.nio.charset.StandardCharsets.UTF_8);try{e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);}finally{e.close();}});var job=period.coaching.enqueue(period.owner,period.request());period.worker.tick();assertEquals("FAILED",period.coaching.job(period.owner,job.id()).state());var repo=new DiaryDiagnostics(CoachingPeriodAiTest.jdbc,CoachingPeriodAiTest.tx);assertEquals("INVALID_PERIOD",repo.read(period.owner,job.id(),"PERIOD",true).raw());assertEquals(1,period.calls.get());}finally{period.stop();}}
    @Test void cancelDuringGenerationPreventsDiagnosticResurrection() throws Exception {UUID entry=fixture.entry("测试取消");var scope=fixture.selected(entry);var preview=fixture.store.preview(fixture.owner,scope);var job=fixture.store.enqueue(fixture.owner,Kind.REVIEW,new Request(UUID.randomUUID(),null,scope,preview.snapshotDigest(),false));fixture.reply.set("LATE_INVALID");fixture.started=new CountDownLatch(1);fixture.proceed=new CountDownLatch(1);var p=spy(fixture.p);doReturn(true).when(p).configured();var worker=new DiaryAiWorker(fixture.store,fixture.index,fixture.cloud,p,fixture.owner,()->true);var executor=Executors.newSingleThreadExecutor();try{var pending=executor.submit(worker::tick);assertTrue(fixture.started.await(5,TimeUnit.SECONDS));fixture.store.cancel(fixture.owner,job.id());fixture.proceed.countDown();pending.get(8,TimeUnit.SECONDS);assertEquals(State.CANCELED,fixture.store.job(fixture.owner,job.id()).state());assertEquals("NOT_RECORDED",diagnostics.read(fixture.owner,job.id(),"REVIEW",true).status());}finally{fixture.proceed.countDown();worker.close();executor.shutdownNow();}}
    @Test void diagnosticStorageFailureRollsBackAndFallsBackToFailedJob(){var failing=spy(DiaryAiPostgresTest.jdbc);doThrow(new org.springframework.dao.DataAccessResourceFailureException("PRIVATE_STORAGE_PROBE")).when(failing).update(startsWith("INSERT INTO diary_diagnostics.failure"),anyMap());fixture.store=new DiaryAiStore(failing,DiaryAiPostgresTest.tx,fixture.p);var task=failReview();assertEquals("NOT_RECORDED",diagnostics.read(fixture.owner,task.job(),"REVIEW",true).status());assertEquals(State.FAILED,fixture.store.job(fixture.owner,task.job()).state());}
    @Test void retentionCountNeverEvictsAnExistingPrivateAnswer(){var issue=assertThrows(DiaryValidation.Issue.class,()->DiaryValidation.check("INVALID",List.of(),"REVIEW"));UUID last=UUID.randomUUID();fixture.store.tx(fixture.owner,()->{for(int i=0;i<100;i++)diagnostics.save(fixture.owner,UUID.randomUUID(),"REVIEW",issue,"fixture","fixture","INVALID",List.of());diagnostics.save(fixture.owner,last,"REVIEW",issue,"fixture","fixture","INVALID",List.of());assertEquals(100L,DiaryAiPostgresTest.jdbc.queryForObject("SELECT count(*) FROM diary_diagnostics.failure WHERE owner_id=:owner AND retention='AVAILABLE'",Map.of("owner",fixture.owner),Long.class));return null;});assertEquals("NOT_RETAINED",diagnostics.read(fixture.owner,last,"REVIEW",true).status());}
}
